SELECT fo.account_id,fo.fund_code,f.fund_name,ROUND(SUM(fo.success_amount),2) amt,COUNT(*) n,MIN(fo.accept_time) first_t FROM ying99_fundtxn.fund_order fo LEFT JOIN ying99_fundtxn.fund_info f ON f.fund_code=fo.fund_code JOIN (SELECT CAST(p.account3_id AS CHAR) account_id,b.fb FROM (SELECT user_id pmid,MIN(created_at) fb FROM ying99_qieman.qwen_user_map WHERE is_deleted=0 GROUP BY user_id HAVING MIN(created_at)>='2026-08-03 00:00:00' AND MIN(created_at)<'{{CUT}}') b JOIN ying99_pomodel.portfolio_manager_info p ON p.po_manager_id=b.pmid WHERE p.account3_id IS NOT NULL) x ON x.account_id=fo.account_id AND fo.accept_time>=x.fb WHERE fo.account_id IN ({{A3Q}}) AND fo.order_type='1' AND fo.accept_time<'{{CUT}}' AND fo.confirm_status<>'3' AND fo.success_amount>0 GROUP BY fo.account_id,fo.fund_code,f.fund_name ORDER BY fo.account_id,amt DESC
